        recent = history[-HISTORY_LEN:]
        rows = (article_row[np.asarray(recent, dtype=np.int64)]
                if isinstance(article_row, np.ndarray)
                else np.array([article_row[a] for a in recent if a in article_row], dtype=np.int64))
        rows = rows[rows >= 0]
        if len(rows):
            users[i] = vectors[rows].mean(axis=0)
    users /= np.linalg.norm(users, axis=1, keepdims=True) + 1e-9
